NOTEBOOKS = json.loads(zlib.decompress(base64.b85decode(PAYLOAD_B85)).decode("utf-8"))


def install_remote_dependencies() -> None:
    subprocess.check_call([sys.executable, "-m", "pip", "install", "-q", "qiskit", "qiskit-aer"])


def execute_notebook(entry: dict) -> None:
    path = entry["path"]
    namespace = {"__name__": "__main__", "__file__": path}
    for number, source in enumerate(entry["cells"], start=1):
        if isinstance(source, list):
            source = "".join(source)
        exec(compile(source, f"{path}:cell-{number}", "exec"), namespace)


def main() -> None:
    install_remote_dependencies()
    successes = 0
    for entry in NOTEBOOKS:
        execute_notebook(entry)
        successes += 1
        print(f"COURSE_FINAL_DERIVED_NOTEBOOK_OK={successes}/12 path={entry['path']}", flush=True)
    print(f"COURSE_FINAL_DERIVED_NOTEBOOKS_OK={successes}/12", flush=True)


if __name__ == "__main__":
    main()
